const SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(10);

#[derive(Parser)]
#[command(version, about = "StarGate SMS Gateway backend")]
struct Args {
    /// Interactively create a new user and exit
    #[arg(long)]
    create_user: bool,

    /// Path to config YAML file (default: config/config.yaml, then config.yaml)
    #[arg(long)]
    config: Option<PathBuf>,

    /// Path to log file; send SIGHUP to reopen after rotation (default: stdout)
    #[arg(long)]
    log: Option<PathBuf>,

    /// Write process PID to this file on startup
    #[arg(long)]
    pid_file: Option<PathBuf>,
}

#[tokio::main]
async fn main() -> ExitCode {
    let args = Args::parse_from(normalize_args(std::env::args_os()));

    let log_file = match logging::init(args.log.as_deref()) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("failed to open log file: {e}");
            return ExitCode::FAILURE;
        }
    };

    match run(args, log_file).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            error!("{e:#}");
            ExitCode::FAILURE
        }
    }
}

async fn run(args: Args, log_file: Option<LogFile>) -> anyhow::Result<()> {
    let _pid_file = match &args.pid_file {
        Some(path) => Some(PidFile::create(path).context("failed to write pid file")?),
        None => None,
    };

    let cfg = load_config(args.config.as_deref())?;

    let db = Db::open(&cfg.database.path)
        .await
        .with_context(|| format!("failed to open database {:?}", cfg.database.path))?;
    db.migrate().await.context("failed to migrate database")?;
    info!(path = %cfg.database.path, "database ready");

    if args.create_user {
        return create_user_interactive(&db).await;
    }

    let sms_out = Arc::new(OutboundClient::new(&cfg.sms)?);
    let streams = Arc::new(StreamManager::new());
    let service = StarGateService::new(db.clone(), streams.clone(), sms_out.clone());

    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    // HTTP server: webhook + health check.
    let http_addr = listen_addr(&cfg.server.webhook_addr);
    let http_listener = TcpListener::bind(&http_addr)
        .await
        .with_context(|| format!("failed to listen on webhook address {http_addr}"))?;
    info!(addr = %cfg.server.webhook_addr, "webhook server listening");
    let app = sms::webhook::router(db.clone(), streams.clone(), cfg.sms.webhook_secret.clone());
    let mut http_task = tokio::spawn(
        axum::serve(http_listener, app)
            .with_graceful_shutdown(wait_for(shutdown_rx.clone()))
            .into_future(),
    );

    if !cfg.sms.webhook_url.is_empty() {
        sms_out
            .register_webhook(&cfg.sms.webhook_url)
            .await
            .context("failed to register webhook with SMS Gate")?;
        info!(url = %cfg.sms.webhook_url, "webhook registered with SMS Gate");
    }

    let grpc_addr = listen_addr(&cfg.server.grpc_addr);
    let grpc_listener = TcpListener::bind(&grpc_addr)
        .await
        .with_context(|| format!("failed to listen on gRPC address {grpc_addr}"))?;
    info!(addr = %cfg.server.grpc_addr, "gRPC server listening");
    let mut grpc_task = tokio::spawn(
        tonic::transport::Server::builder()
            .add_service(StarGateCoreServer::new(service))
            .serve_with_incoming_shutdown(
                TcpListenerStream::new(grpc_listener),
                wait_for(shutdown_rx.clone()),
            ),
    );

    tokio::select! {
        sig = wait_for_shutdown_signal(log_file.as_ref()) => {
            info!(signal = sig?, "shutting down");
        }
        res = &mut grpc_task => bail!("gRPC server stopped unexpectedly: {:?}", res?),
        res = &mut http_task => bail!("webhook server stopped unexpectedly: {:?}", res?),
    }

    let _ = shutdown_tx.send(true);
    // End every SubscribeToInbox stream so the gRPC server can drain.
    streams.close_all();

    match tokio::time::timeout(SHUTDOWN_TIMEOUT, grpc_task).await {
        Ok(Ok(Err(e))) => error!(err = %e, "gRPC shutdown error"),
        Err(_) => error!("gRPC shutdown timed out"),
        _ => {}
    }
    match tokio::time::timeout(SHUTDOWN_TIMEOUT, http_task).await {
        Ok(Ok(Err(e))) => error!(err = %e, "http shutdown error"),
        Err(_) => error!("http shutdown timed out"),
        _ => {}
    }

    info!("shutdown complete");
    Ok(())
}

async fn wait_for(mut rx: watch::Receiver<bool>) {
    let _ = rx.wait_for(|stop| *stop).await;
}

/// Blocks until SIGINT/SIGTERM and returns the signal name. SIGHUP reopens the log file.
#[cfg(unix)]
async fn wait_for_shutdown_signal(log_file: Option<&LogFile>) -> anyhow::Result<&'static str> {
    use tokio::signal::unix::{SignalKind, signal};

    let mut term = signal(SignalKind::terminate())?;
    let mut int = signal(SignalKind::interrupt())?;
    let mut hup = signal(SignalKind::hangup())?;
    loop {
        tokio::select! {
            _ = term.recv() => return Ok("SIGTERM"),
            _ = int.recv() => return Ok("SIGINT"),
            _ = hup.recv() => {
                if let Some(f) = log_file {
                    match f.reopen() {
                        Ok(()) => info!("log file reopened"),
                        Err(e) => error!(err = %e, "failed to reopen log file"),
                    }
                }
            }
        }
    }
}

#[cfg(not(unix))]
async fn wait_for_shutdown_signal(_log_file: Option<&LogFile>) -> anyhow::Result<&'static str> {
    tokio::signal::ctrl_c().await?;
    Ok("ctrl-c")
}

/// Accepts Go-style single-dash long flags (`-config x`) so existing rc.d
/// scripts and habits keep working, by rewriting them to `--config x`.
fn normalize_args(args: impl IntoIterator<Item = OsString>) -> Vec<OsString> {
    const LONG_FLAGS: &[&str] = &["create-user", "config", "log", "pid-file"];
    args.into_iter()
        .map(|arg| {
            if let Some(s) = arg.to_str()
                && let Some(rest) = s.strip_prefix('-')
                && !rest.starts_with('-')
                && LONG_FLAGS.contains(&rest.split('=').next().unwrap_or(""))
            {
                return OsString::from(format!("-{s}"));
            }
            arg
        })
        .collect()
}

/// Go-style ":50051" means "all interfaces"; Rust needs an explicit host.
fn listen_addr(addr: &str) -> String {
    if addr.starts_with(':') {
        format!("0.0.0.0{addr}")
    } else {
        addr.to_string()
    }
}

/// Tries the explicit path first, then falls back to config/config.yaml and config.yaml.
fn load_config(path: Option<&Path>) -> anyhow::Result<Config> {
    let candidates: Vec<&Path> = match path {
        Some(p) => vec![p],
        None => vec![Path::new("config/config.yaml"), Path::new("config.yaml")],
    };
    let mut last_err = None;
    for p in candidates {
        match config::load(p) {
            Ok(cfg) => {
                info!(path = %p.display(), "loaded config");
                return Ok(cfg);
            }
            Err(e) => last_err = Some(e),
        }
    }
    Err(last_err
        .expect("at least one candidate")
        .context("failed to load config"))
}

/// Prompts for credentials and creates a user.
async fn create_user_interactive(db: &Db) -> anyhow::Result<()> {
    let stdin = io::stdin();
    let read_line = || -> io::Result<String> {
        let mut line = String::new();
        stdin.lock().read_line(&mut line)?;
        Ok(line.trim().to_string())
    };

    print!("Username: ");
    io::stdout().flush()?;
    let username = read_line()?;
    if username.is_empty() {
        bail!("username cannot be empty");
    }

    let password = rpassword::prompt_password("Password: ").context("error reading password")?;
    if password.is_empty() {
        bail!("password cannot be empty");
    }

    print!("Global access (HR — sees all groups)? [y/N]: ");
    io::stdout().flush()?;
    let global_access = read_line()?.eq_ignore_ascii_case("y");

    let hash = password::hash(password)
        .await
        .context("error hashing password")?;
    db.create_user(&username, &hash, global_access)
        .await
        .context("error creating user")?;

    println!("User {username:?} created (global_access={global_access})");
    Ok(())
}

/// Writes the PID on creation and removes the file when dropped.
struct PidFile(PathBuf);

impl PidFile {
    fn create(path: &Path) -> io::Result<Self> {
        std::fs::write(path, format!("{}\n", std::process::id()))?;
        Ok(Self(path.to_path_buf()))
    }
}

impl Drop for PidFile {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn norm(args: &[&str]) -> Vec<String> {
        normalize_args(args.iter().map(OsString::from))
            .into_iter()
            .map(|a| a.into_string().unwrap())
            .collect()
    }

    #[test]
    fn single_dash_flags_are_rewritten() {
        assert_eq!(
            norm(&[
                "srv",
                "-config",
                "a.yaml",
                "-pid-file=p",
                "--log",
                "l",
                "-create-user"
            ]),
            [
                "srv",
                "--config",
                "a.yaml",
                "--pid-file=p",
                "--log",
                "l",
                "--create-user"
            ]
        );
    }

    #[test]
    fn other_args_are_untouched() {
        assert_eq!(
            norm(&["srv", "-h", "-x", "--config=a.yaml", "plain"]),
            ["srv", "-h", "-x", "--config=a.yaml", "plain"]
        );
    }

    #[test]
    fn listen_addr_fills_in_host() {
        assert_eq!(listen_addr(":8080"), "0.0.0.0:8080");
        assert_eq!(listen_addr("127.0.0.1:8080"), "127.0.0.1:8080");
    }
}
